-- Dansk portion 4 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3334-6565.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish4'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish4', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3334,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Salt får is til at smelte, også selvom det er under frysepunktet. Derfor bliver der saltet på vejene om vinteren. Men saltet kan skade træer og buske langs vejen, og det kan få biler til at ruste. Mange kommuner prøver derfor at bruge så lidt som muligt.' Hvilken ulempe er der ved at salte vejene ifølge teksten?","o":["Saltet smelter ikke isen i frostvejr","Vejene bliver mere glatte for bilerne","Kommunerne får ikke salt nok","Saltet kan skade planter og biler"],"a":"Saltet kan skade planter og biler","r":"Teksten nævner træer, buske og rust. Det er ulemperne ved noget, som ellers gør vejene sikrere."},
{"l":3355,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Madpakkerne tilhører børnene selv. Hvilket ord passer: 'Børnene finder ___ madpakker frem.'","o":["deres","sine","sin","hans"],"a":"deres","r":"Grundleddet 'børnene' står i flertal, og så bruger man 'deres'. 'Sin' og 'sine' peger på et grundled i ental."},
{"l":3377,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hvis jeg havde ___, at du var syg, havde jeg ringet til dig.'","o":["vidste","vidst","hvidst","visst"],"a":"vidst","r":"Ordet kommer af 'at vide'. Efter 'havde' slutter det på -dst, og d'et skal med, selvom det ikke høres."},
{"l":3399,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Mine sokker er helt ___ efter regnen.'","o":["gennemblødde","genemblødte","gennemblødte","gennembløte"],"a":"gennemblødte","r":"Ordet er sat sammen af 'gennem' med dobbelt n og 'blødte'. D'et skal med, selvom man ikke hører det."},
{"l":3420,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken tegneseriefigur er en lille, klog gallisk kriger, der får kræfter af en trylledrik?","o":["Tintin","Anders And","Rasmus Klump","Asterix"],"a":"Asterix","r":"Asterix bor i en lille landsby i Gallien. Sammen med vennen Obelix narrer han romerne igen og igen."},
{"l":3437,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'hensigt' i sætningen: 'Det var ikke min hensigt at såre dig.'","o":["mening","skyld","regel","vane"],"a":"mening","r":"En hensigt er det, man vil med noget. Sætningen siger, at man ikke ville såre den anden."},
{"l":3459,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Da Mathias vendte tilbage fra sin sommerferie, var de store træer på gaden væk. Hele vejen lå i skarpt sollys. Hans bedstefar stod på fortovet og så op, som om han kunne se noget, der ikke længere var der. – Dem plantede vi, da du ikke var født, sagde han stille.' Hvordan har bedstefaren det?","o":["Han er lettet over, at der nu er mere lys","Han er ked af, at træerne er væk","Han er stolt af det, kommunen har gjort","Han er vred over, at Mathias har været væk"],"a":"Han er ked af, at træerne er væk","r":"Han står og ser op på det tomme sted og siger stille, at han selv var med til at plante dem. Så er han ked af det."},
{"l":3476,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt 'at synge' i kort tillægsform, den form, der står efter 'har': 'Koret har ___ tre sange.'","o":["sang","synger","sunget","syngende"],"a":"sunget","r":"Den korte tillægsform af 'at synge' er 'sunget'. 'Sang' er datid, og 'syngende' er den lange tillægsform."},
{"l":3498,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hensynsleddet: 'Naja sendte sin kusine et postkort.'","o":["Naja","et postkort","sendte","sin kusine"],"a":"sin kusine","r":"Spørg: Hvem fik postkortet? Det er 'sin kusine', som er hensynsleddet. 'Et postkort' er genstandsleddet."},
{"l":3520,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Det er Idas cykel. Hvilket ord passer: 'Laura låner ___ cykel.'","o":["hendes","sin","sit","hans"],"a":"hendes","r":"Cyklen tilhører ikke grundleddet Laura, men Ida. Derfor skal der stå 'hendes' og ikke 'sin'."},
{"l":3540,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvorfor vælger prinsessen Klods-Hans frem for hans kloge brødre?","o":["Han kan hele loven udenad","Han tør tale frit og er ikke bange","Han taler latin bedre end brødrene","Han har den fineste hest"],"a":"Han tør tale frit og er ikke bange","r":"Brødrene kan meget udenad, men de går i stå foran prinsessen. Klods-Hans er sig selv og har svar på rede hånd."},
{"l":3557,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Et barn finder en sten med aftryk af en musling, der levede for millioner af år siden. Hvad kaldes sådan et fund?","o":["et mineral","en krystal","et fossil","en meteorit"],"a":"et fossil","r":"Når et dyr dør og bliver dækket af lag på lag af sand og ler, kan der efter millioner af år være spor af det i stenen."},
{"l":3575,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Solen står op, / træet er grønt, / fuglen på top / synger så skønt.' Hvordan rimer linjerne?","o":["Linje 1 rimer på 2, og linje 3 rimer på 4","Linje 1 rimer på 4, og linje 2 rimer på 3","Kun linje 1 og linje 2 rimer på hinanden","Linje 1 rimer på 3, og linje 2 rimer på 4"],"a":"Linje 1 rimer på 3, og linje 2 rimer på 4","r":"Op rimer på top, og grønt rimer på skønt. Når rimene skifter på den måde, kalder man det krydsrim."},
{"l":3597,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld sætningen: 'Om efteråret flyver store flokke af ___ sydpå.'","o":["gæs","gæss","gåser","gåse"],"a":"gæs","r":"Ental er 'gås'. Flertal får æ og ét s, og der kommer ingen endelse på."},
{"l":3612,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I Sverige har forskere sat små sendere på gråsæler. Senderne viser, hvor dybt dyrene dykker, og hvor længe de bliver under vandet. Forskerne håber, at det kan fortælle dem, hvor sælerne finder føde. Oplysningerne skal også bruges til at beskytte områderne.' Hvad er forskernes mål?","o":["At flytte sælerne til bedre områder","At vide mere for at beskytte sælerne","At fange flere fisk i områderne","At følge sælerne på deres tur i land"],"a":"At vide mere for at beskytte sælerne","r":"Forskerne indsamler viden, og den skal bruges til at beskytte områderne, hvor sælerne lever."},
{"l":3632,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren går ud af klassen, og straks larmer alle. Hvilket ordsprog passer?","o":["Når enden er god, er alting godt","Når det regner på præsten, drypper det på degnen","Når katten er ude, spiller musene på bordet","Når en dør lukkes, åbnes en anden"],"a":"Når katten er ude, spiller musene på bordet","r":"Katten er den, der holder styr på tingene. Når den er væk, tør musene lave ballade, ligesom eleverne her."},
{"l":3652,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er rigtigt her? 'Der svømmer fem ___ på søen i parken.'","o":["ander","ændre","ænner","ænder"],"a":"ænder","r":"Ental er 'and', og i flertal skifter a til æ. Med r før e er det et udsagnsord, der betyder at lave om."},
{"l":3674,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at fryse': 'Sidste vinter ___ søen til is.'","o":["frøs","fryser","frosset","fryse"],"a":"frøs","r":"'At fryse' er uregelmæssigt: fryser, frøs, har frosset. 'Sidste vinter' kræver datid."},
{"l":3695,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Min rygsæk vejer mindst et ton!' Hvilket virkemiddel er der brugt?","o":["rim","overdrivelse","sammenligning","gentagelse"],"a":"overdrivelse","r":"Ingen rygsæk vejer et ton. Forfatteren overdriver for at vise, hvor tung den føles."},
{"l":3718,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find genstandsleddet, selv om det står først: 'Den sidste småkage tog Ahmed.'","o":["Ahmed","tog","Den sidste småkage","tog Ahmed"],"a":"Den sidste småkage","r":"Spørg: Hvem tog? Det gjorde Ahmed, som er grundleddet. Hvad tog han? 'Den sidste småkage', som derfor er genstandsleddet."},
{"l":3736,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange tror, at kamelers pukkel er fyldt med vand. Det er forkert. Puklen består af fedt, som kamelen kan bruge, når den ikke får mad. Når den har sultet længe, bliver puklen slap. Kamelen kan klare sig længe uden vand af andre grunde, for eksempel fordi den sveder meget lidt.' Hvorfor er teksten skrevet?","o":["For at fortælle, hvad kameler spiser i ørkenen","For at forklare, hvordan kamelen samler vand i puklen","For at forklare, hvordan kameler klarer sig uden vand","For at fortælle, at mange tager fejl om puklen"],"a":"For at fortælle, at mange tager fejl om puklen","r":"Teksten begynder med det, mange tror, og siger så, at det er forkert. Puklen er fyldt med fedt, ikke vand."},
{"l":3754,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver gang læreren stillede et spørgsmål, kiggede Benjamin ned i bordet. Han kendte tit svaret, men han ventede på, at nogen sagde hans navn. Denne gang rakte han hånden op, inden han nåede at fortryde. – Det er Nilen, sagde han og mærkede, at han smilede.' Hvad er det nye for Benjamin?","o":["At han selv tør række hånden op","At læreren siger hans navn","At han kender svaret for første gang","At han ikke vil svare på noget længere"],"a":"At han selv tør række hånden op","r":"Før ventede han på at blive spurgt, selvom han tit kendte svaret. Nu rækker han selv hånden op."},
{"l":3773,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Hun ___ skraldespanden før aftensmaden i går.'","o":["tømmede","tømte","tømmte","tømde"],"a":"tømte","r":"Nutid har dobbelt m, men i datid på -te står der kun ét."},
{"l":3795,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Hvor ___ du din dagbog?'","o":["gemer","gæmmer","gemmer","gemmerer"],"a":"gemmer","r":"Ordet staves med e og dobbelt m, fordi vokalen er kort. Nutid ender på -er."},
{"l":3815,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange ord mangler stort bogstav: 'På onsdag tager emil og nadia til frankrig i bilen.'?","o":["ét","to","fire","tre"],"a":"tre","r":"Emil, Nadia og Frankrig er navne og skal have stort bogstav. Ugedagen onsdag skrives med lille."},
{"l":3834,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn mangler på den tomme plads: 'Da vi kom for sent___ sagde læreren: »Døren er låst.«'?","o":["komma","kolon","punktum","spørgsmålstegn"],"a":"komma","r":"Ledsætningen 'Da vi kom for sent' står først og skal følges af komma. Kolonet kommer først efter 'sagde læreren', lige før den direkte tale."},
{"l":3853,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om frugten skal have to kommaer?","o":["Vi købte æbler og pærer til hele klassen i dag.","Hvis du vil kan vi købe æbler pærer og blommer.","Hvis du vil kan vi købe æbler til hele klassen.","Vi købte æbler pærer og blommer til hele klassen."],"a":"Hvis du vil kan vi købe æbler pærer og blommer.","r":"Der skal både komma efter ledsætningen 'Hvis du vil' og efter 'æbler' i opremsningen."},
{"l":3872,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad har man, når man tror på, at man godt kan klare en svær opgave?","o":["selvkritik","medlidenhed","selvtillid","hjemve"],"a":"selvtillid","r":"Tillid er at tro på noget. Selvtillid er at have tillid til sig selv og det, man kan."},
{"l":3894,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord på stregen: 'Hvem har ___ kagen i ni stykker?'","o":["skæret","skærte","skårret","skåret"],"a":"skåret","r":"Efter 'har' skifter æ til å. Der er ét r, og ordet ender på -et."},
{"l":3910,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Det siges om en dreng, der vandt en dyr cykel i en konkurrence: 'Han har skudt papegøjen.' Hvad betyder det?","o":["Han har haft stort held","Han har været meget uheldig","Han har opført sig dårligt","Han har gentaget andre"],"a":"Han har haft stort held","r":"Vendingen kommer fra fugleskydning, hvor den, der skød træfuglen ned, vandt. Den bruges om at have stort held."},
{"l":3929,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'Da Amina kom til Hamborg, lærte hun Tysk af sin nabo Hans.'?","o":["Amina","Tysk","Hamborg","Hans"],"a":"Tysk","r":"Sprog skrives med lille på dansk. Amina og Hans er personer, og Hamborg er en by."},
{"l":3949,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vi har ___ hele vejen hjem, fordi vi glemte vanterne.'","o":["fryset","frøset","frosset","froset"],"a":"frosset","r":"Ordet 'fryse' skifter til o efter 'har'. S'et er dobbelt, fordi o'et er kort."},
{"l":3970,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fyrtårne blev bygget for at vise skibe vej om natten. Hvert fyr havde sit eget lysmønster, så sømændene kunne se, hvor de var. I dag har skibene GPS. Alligevel står de gamle fyr stadig, og nogle af dem bliver brugt som museer eller feriehuse.' Hvordan har GPS ændret fyrtårnenes betydning?","o":["Fyrene er blevet vigtigere end nogensinde før","Fyrene skal nu bruge GPS for at lyse om natten","Fyrene er alle sammen blevet revet ned siden","Fyrene er ikke længere så nødvendige for skibene"],"a":"Fyrene er ikke længere så nødvendige for skibene","r":"Teksten sætter GPS op imod fyrene: Nu har skibene noget andet, så flere fyr har fået nye formål."},
{"l":3992,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'auto-' i 'autograf' og 'automatisk'?","o":["selv","bil","hurtig","fjern"],"a":"selv","r":"Auto kommer fra græsk og betyder selv. En autograf er noget, man selv har skrevet, og en automatisk dør går op af sig selv."},
{"l":4014,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ræven sagde til ravnen: – Du synger sikkert smukkere end alle andre fugle. Ravnen blev stolt og åbnede næbbet for at synge. Osten, den havde i næbbet, faldt ned, og ræven snappede den. – Tak, sagde ræven og løb sin vej.' Hvad er moralen i historien?","o":["Man skal øve sig, før man synger for andre","Man skal passe på folk, der roser én for at få noget","Man skal ikke tale med munden fuld","Man skal altid dele sin ost med andre"],"a":"Man skal passe på folk, der roser én for at få noget","r":"Ræven roser ravnen for at få osten. Det er en fabel, der advarer mod falsk ros."},
{"l":4032,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Cykelsmeden vendte Oskars cykel om og drejede på baghjulet. Den havde larmet i fjorten dage. – Det er bare en løs skærm, sagde han og strammede en skrue. Oskars mor så lettet ud, og Oskar spurgte med det samme, om han nu kunne cykle til fodbold på lørdag.' Hvad havde Oskars mor nok været bange for?","o":["At Oskar skulle stoppe med at gå til fodbold","At cykelsmeden ikke ville se på cyklen","At cyklen var gået rigtig meget i stykker","At skruen var blevet væk på vejen derhen"],"a":"At cyklen var gået rigtig meget i stykker","r":"Hun bliver lettet, da hun hører, at det bare er en løs skærm. Så må hun have været bange for, at det var værre."},
{"l":4050,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi har oplevet, at flere elever går over parkeringspladsen for at komme hurtigt hen til skolen. Det er ikke tilladt. Forældre, der afleverer børn i bil, bedes bruge p-pladsen ved hallen. Vi håber, at I vil hjælpe os, for det handler om børnenes sikkerhed.' Hvorfor skriver skolen til sidst, at det handler om børnenes sikkerhed?","o":["For at sige, at forældrene ikke er gode til at køre bil","For at sige, at der allerede er sket en ulykke","For at bede børnene om at tage bussen fremover","For at give forældrene en god grund til at følge reglen"],"a":"For at give forældrene en god grund til at følge reglen","r":"Skolen forklarer, hvorfor reglen er vigtig. En god begrundelse gør det mere sandsynligt, at folk følger den."},
{"l":4070,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Jylland er en stor ___ af Danmark. Hvad er stavet rigtigt?","o":["landsdel","landdel","lansdel","landsdæl"],"a":"landsdel","r":"Ordet har fuge-s efter 'land'. D'et i 'land' skal skrives, selvom det ikke høres."},
{"l":4092,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Den bedste ___, jeg har fået, var en ny cykel.'","o":["fødseldagsgave","fødselsdagsgave","fødselsdaggave","fødselsdags gave"],"a":"fødselsdagsgave","r":"Ordet har to fuge-s'er: efter 'fødsel' og efter 'dag'. Det skrives i ét ord."},
{"l":4113,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Den nye pedel talte ikke ret meget. Efter tre uger vidste eleverne kun, at han hed Amir. Så gik klaveret i musiklokalet i stykker, og han kom for at se på det. Da han havde strammet nogle strenge, satte han sig og spillede et helt stykke uden noder. Der blev stille. Ved frokost kom tre elever hen og spurgte, om han ville lære dem det.' Hvad var det, der ændrede elevernes syn på Amir?","o":["At han fik klaveret til at virke igen","At læreren bad dem om at tale med ham","At de hørte, hvad han kunne","At han flyttede ned i musiklokalet"],"a":"At de hørte, hvad han kunne","r":"Da han spillede, opdagede eleverne noget, de ikke vidste om ham. Det var musikken, de ville lære, ikke at lave klaverer."},
{"l":4131,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Tak for en super god fest, skrev Lærke på skolens side. Musikken var høj, så man ikke kunne tale. Maden var kold, da vi nåede frem, og halvdelen af lyset virkede ikke. Jeg glæder mig bestemt til næste år!' Hvad mener Lærke i virkeligheden?","o":["At hun var meget glad for festen","At hun ikke nåede til festen i år","At hun vil hjælpe med festen næste år","At festen var en stor skuffelse"],"a":"At festen var en stor skuffelse","r":"Hun bruger ironi: Ordene er rosende, men alt det, hun beskriver, er dårligt."},
{"l":4150,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Bronze består af kobber og tin, der er smeltet sammen. Hvad kaldes sådan en blanding af metaller?","o":["en legering","et mineral","en malm","en krystal"],"a":"en legering","r":"Ved at smelte metaller sammen får man en legering, der ofte er stærkere end metallerne hver for sig."},
{"l":4169,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at skyde': 'Hvem ___ det sidste mål i søndags?'","o":["skudt","skød","skyder","skyde"],"a":"skød","r":"'I søndags' viser, at det er sket, så der skal stå datid. 'At skyde' bøjes skyder, skød, har skudt."},
{"l":4191,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Cyklerne bliver lavet på en stor ___ i udkanten af byen.'","o":["fabrikk","fapprik","fabrik","fabbrik"],"a":"fabrik","r":"Ordet har ét b og ender på -ik med kun ét k, selvom trykket ligger på sidste stavelse."},
{"l":4210,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler i ordsproget 'Mange kokke ___ maden'?","o":["forbedrer","fordobler","forsøder","fordærver"],"a":"fordærver","r":"Fordærve betyder at ødelægge. Ordsproget siger, at det går galt, når for mange vil bestemme over det samme."},
{"l":4225,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil det gamle råd 'Skomager, bliv ved din læst' sige?","o":["Hold dig til det, du forstår dig på","Køb altid dine sko hos den samme mand","Bliv hjemme og lav dit arbejde færdigt","Sæt dig ned og læs en god bog i stedet"],"a":"Hold dig til det, du forstår dig på","r":"En læst er den form, skomageren bygger skoen på. Rådet siger, at man skal blande sig uden om det, man ikke ved noget om."},
{"l":4247,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ali 'slugte en kamel' på klassens møde. Hvad gjorde han?","o":["Han spiste alt for meget til klassens fest","Han accepterede noget, han egentlig var imod","Han sagde højt og tydeligt, at han var uenig","Han fortalte en historie, som ingen troede på"],"a":"Han accepterede noget, han egentlig var imod","r":"En kamel er svær at sluge. Vendingen bruges, når man går med til noget ubehageligt for at komme videre."},
{"l":4268,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at ligge': 'Bogen har ___ på bordet hele ugen.'","o":["lagt","lå","ligget","ligger"],"a":"ligget","r":"Bogen ligger bare stille, så det er 'at ligge', og tillægsformen er 'ligget'. 'Lagt' hører til 'at lægge'."},
{"l":4290,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der stå komma: 'Da klokken ringede løb alle ud i skolegården.'?","o":["klokken","løb","alle","ringede"],"a":"ringede","r":"'Da klokken ringede' er en ledsætning, der står først. Efter en ledsætning skal der altid komma."},
{"l":4310,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Om en person siger man, at hun 'har ben i næsen'. Hvad er hun så?","o":["bestemt og ved, hvad hun vil","forkølet og snøfter hele tiden","nysgerrig på andres hemmeligheder","stolt og vil ikke tale med nogen"],"a":"bestemt og ved, hvad hun vil","r":"Det er ros. Hun lader sig ikke slå ud, men siger sin mening og tager selv fat."},
{"l":4330,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lærkens sang er blevet sjældnere over de danske marker. Lærken bygger rede på jorden, men de store maskiner kører oftere end før. Mange unger når ikke at flyve fra reden. Nogle landmænd lader nu små pletter ligge urørte midt på marken, så fuglene får ro.' Hvad er sammenhængen mellem maskinerne og lærken?","o":["Maskinerne larmer så meget, at lærken ikke kan synge","Maskinerne kan ødelægge reder, før ungerne er klar","Maskinerne bruger de frø, som lærken skal spise","Maskinerne skaber små pletter, hvor lærken bor"],"a":"Maskinerne kan ødelægge reder, før ungerne er klar","r":"Reden ligger på jorden, og ungerne når ikke væk. Man kan slutte, at maskinerne rammer rederne."},
{"l":4348,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'tapper'?","o":["tavs","trist","modig","doven"],"a":"modig","r":"En tapper person holder ud og tør møde noget farligt eller svært, altså en modig person."},
{"l":4370,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'fast' i sætningen 'Maja har fået fast arbejde i bageriet'?","o":["hårdt og ikke flydende","bundet stramt til noget andet med et reb","tungt og meget hårdt at lave","varigt og ikke kun for en kort tid"],"a":"varigt og ikke kun for en kort tid","r":"Fast arbejde er et job, man beholder, til det bliver opsagt. Ordet 'fast' skifter betydning efter sammenhængen."},
{"l":4390,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Grønland er verdens største ø. Næsten hele landet er dækket af indlandsis, så folk bor langs kysterne. Mellem byerne er der ikke veje, så man rejser med båd eller fly. Derfor koster mange ting mere i butikkerne end i Danmark.' Hvad er årsagen til de høje priser ifølge teksten?","o":["Det er dyrt at bringe varer rundt uden veje","Der er for få mennesker, der vil handle","Der er for mange butikker langs kysterne","Isen gør, at varerne bliver dårlige hurtigt"],"a":"Det er dyrt at bringe varer rundt uden veje","r":"Ordet 'derfor' kobler de manglende veje til priserne. Man må selv slutte, at transporten gør varerne dyrere."},
{"l":4408,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'forlegen'?","o":["genert","selvsikker","flov","tavs"],"a":"selvsikker","r":"Den forlegne bliver usikker og flov, mens den selvsikre står ved sig selv uden at blive genert. 'Genert' og 'flov' ligger tæt på forlegen."},
{"l":4430,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'nøglen' i sætningen 'Træning er nøglen til succes'?","o":["en lille ting af metal til en lås","et rundt bundt garn til strikning","det, der gør noget muligt","en tabel med svar bag i en bog"],"a":"det, der gør noget muligt","r":"Her er ordet brugt i overført betydning. Ligesom en nøgle åbner en dør, åbner træning vejen til at blive god."},
{"l":4445,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer på en person, der tager hensyn til, hvordan andre har det?","o":["flittig","selvglad","tapper","betænksom"],"a":"betænksom","r":"Den, der er betænksom, tænker på andre. En flittig person arbejder meget, og en tapper person er modig. Selvglad handler om at tænke højt om sig selv."},
{"l":4466,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavning: 'I Egypten kan man se den store ___ ved Giza.'","o":["pyramide","piramide","pyrramide","pyrimide"],"a":"pyramide","r":"Ordet kommer fra græsk og har y i første stavelse. Vokalen efter r er et a."},
{"l":4487,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hensynsleddet: 'Hun viste ham billederne.'","o":["Hun","ham","billederne","viste"],"a":"ham","r":"Billederne bliver vist til ham, så 'ham' er hensynsled. 'Billederne' er det, der vises, altså genstandsled."},
{"l":4505,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'skat' i sætningen 'Alle, der tjener penge, skal betale skat'?","o":["en værdifuld kiste, der er gravet ned","et kærligt navn til en, man holder rigtig meget af","penge, man betaler til staten og kommunen","penge, man sparer op til sin pension"],"a":"penge, man betaler til staten og kommunen","r":"Skat er de penge, staten og kommunen får ind og bruger på blandt andet skoler, veje og sygehuse."},
{"l":4526,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Carl Nielsen er en berømt dansk ___.'","o":["kompunist","komponisst","kommponist","komponist"],"a":"komponist","r":"Ordet ender på -ist med ét s, og der er kun ét m foran p."},
{"l":4543,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad laver en 'anklager' i en retssag?","o":["prøver at vise, at den tiltalte er skyldig","afgør, hvilken straf der skal gives","forsvarer den, der er tiltalt","skriver om sagen i avisen"],"a":"prøver at vise, at den tiltalte er skyldig","r":"Anklageren fremlægger beviserne mod den tiltalte. Det er forsvareren, der taler den tiltaltes sag, og dommeren, der afgør straffen."},
{"l":4564,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer, når det er børnene, klovnen får til at grine: 'Klovnen morede ___ i en hel time.'","o":["sig","dem","de","deres"],"a":"dem","r":"Klovnen morede nogle andre, nemlig børnene. Derfor hedder det 'dem'. 'Sig' ville betyde, at klovnen selv havde det sjovt."},
{"l":4586,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Håndbold er en populær ___ i Danmark.'","o":["sportgren","sporsgren","sportsgren","sports gren"],"a":"sportsgren","r":"Ordet har fuge-s mellem 'sport' og 'gren'. T'et fra 'sport' skal med."},
{"l":4600,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Min far kalder det at lave morgenmad. Han har sat mælken på bordet.' Hvad er det humoristiske i teksten?","o":["Faren kan ikke lide mælk til morgenmaden","Faren spiser sin morgenmad ved bordet","Mælken er blevet for gammel til at drikke","Han kalder det at lave mad, men gør næsten intet"],"a":"Han kalder det at lave mad, men gør næsten intet","r":"'At lave morgenmad' lover meget, men han har kun sat mælken på bordet. Forskellen er det sjove."},
{"l":4619,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord ligger tættest på 'oprigtig'?","o":["ærlig","ivrig","rolig","stolt"],"a":"ærlig","r":"Oprigtig betyder, at man mener det, man siger, og ikke lader som om. Det kalder man også at være ærlig."},
{"l":4641,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'én' i sætningen: 'Vi har kun én hund, men to katte.'","o":["kendeord","talord","stedord","navneord"],"a":"talord","r":"'Én' fortæller antallet og stilles over for 'to'. Her er det derfor et talord og ikke et kendeord."},
{"l":4658,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Om aftenen kan store elever gå på hold på ___.'","o":["ungdomskole","ungdomskolle","ungdomsskole","ungsdomsskole"],"a":"ungdomsskole","r":"Der er fuge-s efter 'ungdom', og 'skole' begynder også med s. Derfor står der to s'er."},
{"l":4679,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vælg det rigtige ord: 'Den nye bro er en gevinst for bilisterne, for den vil ___ rejsetiden med en halv time.'","o":["forlænge","forklare","forsvare","forkorte"],"a":"forkorte","r":"Broen er en gevinst, så turen må blive kortere. At forkorte er at gøre noget kortere."},
{"l":4700,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad hedder de tre røvere i 'Folk og røvere i Kardemomme by'?","o":["Kasper, Jesper og Jonatan","Rip, Rap og Rup","Pingo, Pelle og Skæg","Bastian, Tobias og Sofie"],"a":"Kasper, Jesper og Jonatan","r":"Thorbjørn Egners tre røvere stjæler i byen, men bliver til sidst gode borgere. Bastian er derimod byens politimester."},
{"l":4715,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg havde arbejdet to måneder på min bog om min bedstefars fiskerbåd, og i dag læste jeg op for klassen. Da jeg var færdig, sagde Louis: – Hvor er det kedeligt med både. Han har fuldstændig ret, for hvad ved han egentlig om både? Han har aldrig engang været på en.' Hvad mener fortælleren med ordene fuldstændig ret?","o":["Fortælleren synes også, at både er kedelige","Fortælleren mener det modsatte af det, der står","Fortælleren fortryder at have skrevet bogen","Fortælleren vil lære Louis noget om både"],"a":"Fortælleren mener det modsatte af det, der står","r":"Lige bagefter skriver fortælleren, at Louis slet ikke ved noget om både. Så er 'fuldstændig ret' ikke ment alvorligt."},
{"l":4732,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'mærke' i sætningen 'Bilen er af et kendt mærke'?","o":["en plet eller skramme i lakken","et lille stykke papir på et brev","navnet på det firma, der laver bilen","en fornemmelse inde i kroppen"],"a":"navnet på det firma, der laver bilen","r":"Et bilmærke er det navn, som en producent sælger sine biler under. 'Mærke' kan også være en plet eller et frimærke."},
{"l":4754,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer? 'Trods regnen var stemningen ___, og alle smilede og sang.'","o":["trykket","anspændt","dyster","opløftet"],"a":"opløftet","r":"Når alle smiler og synger, er stemningen glad og let. De tre andre ord beskriver en dårlig stemning."},
{"l":4773,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find genstandsleddet: 'Læreren roste dem for deres arbejde.'","o":["dem","Læreren","for deres arbejde","roste"],"a":"dem","r":"Spørg: Hvem roste læreren? Svaret 'dem' er genstandsleddet. 'For deres arbejde' begynder med et forholdsord."},
{"l":4795,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led er 'en krone' i sætningen: 'Bageren gav kunden en krone tilbage.'","o":["hensynsled","genstandsled","grundled","forholdsordsled"],"a":"genstandsled","r":"Spørg: Hvad gav bageren? Svaret er genstandsleddet. 'Kunden' er hensynsled, fordi kunden får kronen."},
{"l":4807,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord mangler? 'Det er ___ at cykle uden lygter i mørke, så husk at tænde dem.'","o":["ubetydeligt","uundgåeligt","uansvarligt","uafhængigt"],"a":"uansvarligt","r":"Den, der cykler uden lys, kan ikke ses af bilisterne. Det er uansvarligt, fordi det er farligt for både en selv og andre."},
{"l":4828,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at ligge': 'Hunden blev ___ på gulvet, da vi gik.'","o":["ligget","lå","ligger","liggende"],"a":"liggende","r":"Efter 'blive' i denne betydning står den lange tillægsform: 'blive liggende', 'blive siddende', 'blive stående'."},
{"l":4850,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordet: 'Trods regnen spillede vi videre.'","o":["Trods","regnen","spillede","videre"],"a":"Trods","r":"'Trods' står foran navneordet 'regnen' og knytter det til sætningen. 'Videre' er et biord."},
{"l":4867,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at en besked er 'tvetydig'?","o":["at den er skrevet to gange","at den kan forstås på to måder","at den er helt klar for alle","at den er sendt af to personer"],"a":"at den kan forstås på to måder","r":"'Tve-' er et gammelt ord for to. Noget tvetydigt har to mulige betydninger, så man kan misforstå det."},
{"l":4889,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad er en selvbiografi?","o":["En bog, en person skriver om en anden persons liv","En bog, der viser, hvordan man selv kan lære noget","En bog, en person skriver om sit eget liv","En bog, en forfatter digter om en person, der ikke findes"],"a":"En bog, en person skriver om sit eget liv","r":"Selv- betyder her, at forfatteren skriver om sig selv. H.C. Andersen skrev for eksempel 'Mit Livs Eventyr'."},
{"l":4905,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'ensformig'?","o":["kedelig","monoton","ensartet","afvekslende"],"a":"afvekslende","r":"Noget ensformigt er det samme hele tiden. Noget afvekslende byder på skift og variation."},
{"l":4927,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'stemme blankt' ved et valg?","o":["at aflevere en stemmeseddel uden at sætte kryds","at stemme på det parti, der er størst i forvejen","at stemme ved at sende et brev til kommunen","at stemme, længe før de andre har stemt"],"a":"at aflevere en stemmeseddel uden at sætte kryds","r":"Blank betyder her tom. En blank stemme viser, at man har deltaget uden at vælge nogen af mulighederne."},
{"l":4946,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'God ___ er vigtig på et hold.'","o":["komunikation","kommunikation","kommunigation","kommunikasjon"],"a":"kommunikation","r":"Ordet har dobbelt m efter o, ét n og k før -ation."},
{"l":4965,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'motivation'?","o":["evne til at bevæge sig hurtigt","en plan over ugens lektier","lyst og grund til at gøre noget","følelsen af at være træt af noget"],"a":"lyst og grund til at gøre noget","r":"Motivation er det, der driver en til at gå i gang og blive ved, også når det er svært."},
{"l":4985,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem skrev 'Alice i Eventyrland'?","o":["Roald Dahl","Mark Twain","Jules Verne","Lewis Carroll"],"a":"Lewis Carroll","r":"Lewis Carroll var en engelsk forfatter. I bogen falder Alice ned i et kaninhul og kommer til en mærkelig verden."},
{"l":5002,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'nedlægge' i 'Kommunen vil nedlægge skolen'?","o":["oprette","lukke","flytte","omtale"],"a":"oprette","r":"At nedlægge en skole er at lukke den for altid. At oprette er at starte noget nyt."},
{"l":5018,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'I toget tjekker en ___ billetterne.'","o":["kondukter","konduktør","konducktør","konduktøer"],"a":"konduktør","r":"Ordet for personen ender på -ør, og der står k foran t."},
{"l":5040,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'påfaldende'?","o":["pålidelig","påtrængende","iøjnefaldende","pludselig"],"a":"iøjnefaldende","r":"Noget påfaldende vækker opmærksomhed, fordi det skiller sig ud. Det gør noget iøjnefaldende også."},
{"l":5059,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at dø': 'Den gamle tomatplante ___ i frosten i sidste uge.'","o":["død","dør","dø","døde"],"a":"døde","r":"'I sidste uge' kræver datid, som er 'døde'. 'Død' står efter 'er', som i 'planten er død'."},
{"l":5081,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem skrev bøgerne om drengen Silas og den sorte hoppe?","o":["Cecil Bødker","Bjarne Reuter","Ole Lund Kirkegaard","Thorbjørn Egner"],"a":"Cecil Bødker","r":"Cecil Bødker var en dansk forfatter. Silas er en dreng, der klarer sig med sin fløjte og sine gode idéer."},
{"l":5102,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hver morgen sagde buschaufføren det samme til Mads: – Godmorgen, kaptajn. Mads syntes, det var lidt pinligt, og svarede kun med et nik. I denne uge kørte en vikar, som ikke sagde noget. Fredag steg Mads ind i bussen og hørte sig selv sige: – Godmorgen, kaptajn.' Hvad opdager Mads?","o":["At vikaren er en rigtig kaptajn","At han faktisk godt kunne lide hilsenen","At han har taget den forkerte bus hele ugen","At hilsenen altid har været pinlig for ham"],"a":"At han faktisk godt kunne lide hilsenen","r":"Han syntes, at hilsenen var pinlig, men da den er væk, siger han den selv. Så har han alligevel holdt af den."},
{"l":5122,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'stram' i sætningen 'Kommunen har en stram økonomi'?","o":["med mange penge i overskud","med en skarp og sur smag","med få penge at bruge af","med tøj, der sidder tæt"],"a":"med få penge at bruge af","r":"En stram økonomi betyder, at der ikke er plads til ekstra udgifter. Ordet bruges i overført betydning."},
{"l":5138,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Jeg ___ på, hvordan gåden skal løses.'","o":["spekulere","spikulerer","spekuleret","spekulerer"],"a":"spekulerer","r":"Det sker nu, så ordet ender på -erer. Vokalen efter p er et e."},
{"l":5157,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket led er ledsætningen i: 'At du kom, gjorde mig glad.'","o":["grundled","genstandsled","hensynsled","udsagnsled"],"a":"grundled","r":"Spørg: Hvad gjorde mig glad? Svaret er 'at du kom', så ledsætningen er grundled."},
{"l":5176,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det er svært at måle lykke. Spørger man folk, om de er lykkelige, svarer mange ud fra, hvordan dagen har været. Når det regner, siger flere nej, end når solen skinner. Undersøgelser af lykke i forskellige lande skal derfor læses med forsigtighed.' Hvad er problemet med sådanne undersøgelser?","o":["De bliver lavet for sjældent til at give mening","Svarene påvirkes af ting, der ikke har med lykke at gøre","De får kun svar fra folk, der er ulykkelige med deres liv","Folk kan ikke forstå, hvad ordet lykke betyder"],"a":"Svarene påvirkes af ting, der ikke har med lykke at gøre","r":"Vejret er ikke lykke, men det ændrer svarene. Derfor kan man ikke stole fuldt ud på tallene."},
{"l":5198,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Min mor ___ ikke, at jeg kommer for sent hjem.'","o":["acceptere","accepteret","accepterer","akcepterer"],"a":"accepterer","r":"Ordet begynder med acc og står i nutid med -erer."},
{"l":5220,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Layla har 'rutine' i at holde oplæg. Hvad betyder det?","o":["hun har lyst til at prøve det for allerførste gang","hun bliver bange, når hun skal stå foran mange","hun har fået lov til at gøre det foran hele skolen","hun har erfaring, fordi hun har gjort det mange gange"],"a":"hun har erfaring, fordi hun har gjort det mange gange","r":"Rutine er den øvelse, man får ved at gøre noget tit. Så går det næsten af sig selv."},
{"l":5236,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der er to slags mennesker på et bibliotek, sagde min mormor: dem, der leder efter en bestemt bog, og dem, der lader bogen finde dem. Jeg gik der hver lørdag i årevis uden en plan. Det var sådan, jeg fandt digte, som ingen havde anbefalet mig, og som jeg stadig kan udenad.' Hvilken slags menneske er fortælleren?","o":["Den, der lader bogen finde sig","Den, der kun læser det, som mormoren anbefaler","Den, der kommer forbi med en liste med bøger","Den, der kun går på biblioteket for at lære digte"],"a":"Den, der lader bogen finde sig","r":"Fortælleren går uden plan og finder bøger, som ingen har anbefalet. Det passer på 'dem, der lader bogen finde dem'."},
{"l":5257,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Find det rigtige ord: 'Han måtte ___ sin påstand, da nye oplysninger viste, at den var forkert.'","o":["bekræfte","tilbagekalde","fremsætte","understrege"],"a":"tilbagekalde","r":"Når en påstand viser sig forkert, må man tage den tilbage, og det betyder at tilbagekalde."},
{"l":5278,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken slags stedord er 'nogen' i: 'Er der nogen hjemme?'","o":["ejestedord","påpegende stedord","ubestemt stedord","spørgende stedord"],"a":"ubestemt stedord","r":"'Nogen' peger ikke på bestemte personer. Derfor er det et ubestemt stedord."},
{"l":5296,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forestil dig en undersøgelse, der viser, at elever med madpakke får bedre karakterer end elever, der køber mad. Forældre, der smører madpakke, har måske også tid til at hjælpe med lektier. Det er derfor ikke sikkert, at det er madpakken, der gør forskellen.' Hvilken tankefejl advarer teksten imod?","o":["At tro, at madpakker altid smager bedre end købt mad","At tro, at lektiehjælp giver dårligere karakterer","At tro, at forældre ikke har tid til lektiehjælp","At tro, at det er madpakken, der giver de gode karakterer"],"a":"At tro, at det er madpakken, der giver de gode karakterer","r":"At to ting følges ad, beviser ikke, at den ene skaber den anden. Her kan en tredje ting forklare det."},
{"l":5306,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"En stærk vind, der drejer rundt i ring: Hvad er stavet rigtigt?","o":["hvirvelvind","virvelvind","hvirvlevind","hvirrelvind"],"a":"hvirvelvind","r":"Første del begynder med stumt h foran v, ligesom 'hvid'. Der står v efter r."},
{"l":5325,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'foranderlig'?","o":["vedvarende","skiftende","fortrolig","forudsigelig"],"a":"skiftende","r":"Noget foranderligt ændrer sig tit, som vejret i april. 'Vedvarende' siger det modsatte."},
{"l":5344,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om sengetid er rigtig?","o":["Selvom han var ikke træt, gik han i seng.","Selvom han ikke var træt, han gik i seng.","Selvom han ikke var træt, gik han i seng.","Selvom var han ikke træt, gik han i seng."],"a":"Selvom han ikke var træt, gik han i seng.","r":"I ledsætningen står 'ikke' før udsagnsordet. Efter en ledsætning kommer udsagnsleddet først i hovedsætningen."},
{"l":5366,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Over middagsbordet sagde farfar, at alting var bedre i gamle dage. Mathilde spurgte, om det også gjaldt tandlægen. Farfar tænkte sig om. Det gjaldt for det meste, sagde han så. Mor grinede, og farfar blinkede til Mathilde.' Hvad viser farfars blink?","o":["At han er vred på Mathilde over spørgsmålet","At han mener, at tandlægen var bedre før","At han vil have Mathilde til at tie stille","At han godt ved, at hans påstand er overdrevet"],"a":"At han godt ved, at hans påstand er overdrevet","r":"Han trækker lidt i land og blinker. Det viser, at han selv kan se det sjove i det, han sagde."},
{"l":5386,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Der er noget, der hedder et ekkokammer. Det opstår, når du på nettet kun ser det, du allerede er enig i. Hver gang du klikker på noget, får du mere af det samme. Til sidst virker det, som om alle mener, hvad du mener. Det kan gøre det svært at forstå andre.' Hvad er faren ifølge teksten?","o":["At man får et forkert billede af, hvad andre mener","At alle på nettet kommer til at mene det samme","At man bliver nødt til at klikke på alt, man ser","At man holder op med at have sin egen mening"],"a":"At man får et forkert billede af, hvad andre mener","r":"Når du kun ser det, du er enig i, ser det ud, som om alle er enige. Det er et forkert billede."},
{"l":5400,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Min klasse er en flok stære. Når den ene vender, vender alle, og ingen ved, hvem der begyndte.' Hvad mener skribenten?","o":["Eleverne er gode til at samarbejde om opgaver","Eleverne følger flokken uden at tænke selv","Eleverne larmer meget i frikvartererne","Eleverne har svært ved at finde vej rundt"],"a":"Eleverne følger flokken uden at tænke selv","r":"Stære flyver i store flokke, der vender på samme tid. Billedet viser, at klassen gør det samme som alle andre."},
{"l":5421,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvor mange udsagnsled er der i: 'Sara løb hjem, tog sin taske og cyklede til stranden.'","o":["to","fire","tre","én"],"a":"tre","r":"'Løb', 'tog' og 'cyklede' er tre udsagnsled. De deler det samme grundled, nemlig Sara."},
{"l":5442,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når en ny medicin skal testes, får nogle af forsøgspersonerne rigtig medicin, mens andre får en pille uden virkning. Hverken de eller lægen ved, hvem der får hvad. Det skyldes, at man kan få det bedre, blot fordi man tror på behandlingen.' Hvorfor ved lægen det ikke?","o":["For at spare penge på den rigtige medicin","For at ingen skal kunne klage over den pille, de fik","For at forsøgspersonerne hurtigere får det bedre","For at lægens forventninger ikke skal påvirke resultatet"],"a":"For at lægens forventninger ikke skal påvirke resultatet","r":"Teksten fortæller, at forventninger kan ændre oplevelsen. Man kan slutte, at lægens viden også kunne påvirke forsøget."},
{"l":5462,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Polarforskerne tog ud på en lang ___ til Grønland.'","o":["ekspedition","ekspidition","expedition","eksbedition"],"a":"ekspedition","r":"Ordet har eks, derefter e efter p, og slutter på -tion."},
{"l":5483,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'afmagt'?","o":["trangen til at bestemme over andre","følelsen af ikke at kunne gøre noget","følelsen af at have masser af energi","lysten til at prøve noget nyt"],"a":"følelsen af ikke at kunne gøre noget","r":"Forstavelsen 'af-' viser her, at noget er væk. I afmagt mangler man magten til at ændre situationen."},
{"l":5500,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Fire ud af fem elever på Søndervangskolen er glade for at gå i skole, viser en ny undersøgelse. Skolen sendte spørgeskemaet ud til alle 420 elever, og 40 svarede.' Hvad bør få læseren til at tvivle på resultatet?","o":["Der var for mange elever at spørge","Spørgsmålet handler om glæde","Kun få af eleverne har svaret","Fire ud af fem er for få til en undersøgelse"],"a":"Kun få af eleverne har svaret","r":"Under en tiendedel svarede. De 40 kan være meget forskellige fra de 380, der ikke gjorde, så tallet siger lidt om alle eleverne."},
{"l":5521,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'legitimt' i sætningen 'Det er et legitimt spørgsmål'?","o":["dumt og overflødigt","hemmeligt og skjult","svært og indviklet","rimeligt og i orden"],"a":"rimeligt og i orden","r":"Noget legitimt er i orden og har gode grunde bag sig. Ordet kommer af latin for lov."},
{"l":5542,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord fortæller ledsætningen mere om: 'Min tante, der bor i Skagen, maler billeder.'","o":["tante","Skagen","billeder","maler"],"a":"tante","r":"Ledsætningen 'der bor i Skagen' fortæller noget om min tante."},
{"l":5558,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'gå i brechen' for nogen?","o":["at bryde et løfte til nogen","at træde frem og forsvare nogen","at bygge noget sammen med nogen","at flytte langt væk fra nogen"],"a":"at træde frem og forsvare nogen","r":"En breche er et hul i en mur. Den, der går i brechen, stiller sig op og tager kampen for en anden."},
{"l":5581,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En app bruger en 'algoritme' til at vælge videoer. Hvad er det?","o":["et billede, der reklamerer for appen på nettet","en person, der kontrollerer alle videoer","en række faste regler, som en computer følger","en samling af gamle videoklip fra brugerne"],"a":"en række faste regler, som en computer følger","r":"En algoritme er en trinvis fremgangsmåde. Den afgør for eksempel, hvad du får vist på din skærm."},
{"l":5600,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Filmen varer tre timer. Jeg har set kortere vintre.' Hvad er anmelderens vurdering?","o":["Filmen foregår om vinteren","Filmen er kortere end ventet","Filmen er kold, men smuk","Filmen føles alt for lang"],"a":"Filmen føles alt for lang","r":"Overdrivelsen med vinteren er en spydig måde at sige, at filmen slæber sig af sted. Den handler om tid, ikke om årstid."},
{"l":5618,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Om Ahmed siger man, at han er en meget 'umiddelbar' person. Hvad betyder det?","o":["naturlig og direkte","mistænksom og lukket","langsom og eftertænksom","fin og fornem"],"a":"naturlig og direkte","r":"En umiddelbar person er sig selv uden at spille skuespil. Ordet kan også betyde 'med det samme'."},
{"l":5639,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig, når 'fornavn og efternavn' trækkes sammen?","o":["for og efternavn","for- og efternavn","for-og efternavn","for og -efternavn"],"a":"for- og efternavn","r":"Bindestregen står, hvor en del af ordet er sparet væk, altså lige efter 'for' og med mellemrum bagefter."},
{"l":5656,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'ignorance'?","o":["overdreven tro på sig selv","stærk frygt for noget nyt","mangel på viden om noget","dyb skuffelse over et nederlag"],"a":"mangel på viden om noget","r":"Ignorance betyder uvidenhed. Det hører sammen med 'ignorant', som bruges om en person, der ikke ved noget om et emne."},
{"l":5677,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket komma kalder man et slutkomma?","o":["Kommaet foran en ledsætning","Kommaet i et decimaltal","Kommaet i en opremsning","Kommaet efter en ledsætning"],"a":"Kommaet efter en ledsætning","r":"Slutkommaet viser, hvor en ledsætning slutter, og det skal altid sættes."},
{"l":5699,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken forskel er der på et sagn og et eventyr?","o":["Et sagn er knyttet til et bestemt sted eller en person","Et sagn er opdigtet af én bestemt, kendt forfatter","Et sagn handler om talende dyr og slutter med en moral","Et sagn er en ganske kort tekst skrevet på rim og vers"],"a":"Et sagn er knyttet til et bestemt sted eller en person","r":"Et sagn foregår tit et sted, man kan pege på, og folk kunne tro, at det var sandt. Et eventyr foregår derimod 'et sted langt borte'."},
{"l":5716,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Myren slæbte korn hjem hele sommeren, mens græshoppen sang. Da vinteren kom, bankede græshoppen sulten på myrens dør. Den, der ikke sørger for sig i tide, må gå uden.' Hvilken genre er det?","o":["eventyr","fabel","sagn","myte"],"a":"fabel","r":"Dyrene taler og opfører sig som mennesker, og til sidst kommer en moral. Det er det, der gør teksten til en fabel og ikke et eventyr."},
{"l":5738,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Den gamle gangbro over Lindå lukker på mandag. Kommunen oplyser, at to bjælker er rådne, og at broen først åbner igen til sommer. Skoleeleverne fra Nørrevang må derfor cykle en omvej på tre kilometer.' Hvad kan man slutte om eleverne fra Nørrevang?","o":["De skal gå på en anden skole til sommer","Det var dem, der opdagede de rådne bjælker","Deres skolevej bliver længere i en periode","De kan slet ikke længere cykle til skole"],"a":"Deres skolevej bliver længere i en periode","r":"Omvejen gælder, mens broen er lukket, altså indtil sommer. Eleverne kan stadig cykle, men vejen er tre kilometer længere."},
{"l":5760,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal ledsætningen afsluttes med komma: 'Bogen som jeg lånte på biblioteket var spændende.'?","o":["lånte","var","spændende","biblioteket"],"a":"biblioteket","r":"Den indskudte ledsætning 'som jeg lånte på biblioteket' slutter efter 'biblioteket'."},
{"l":5780,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Find den rigtige plads til kommaet: 'Det der skete i går glemmer jeg aldrig.'","o":["efter går","efter skete","efter glemmer","efter jeg"],"a":"efter går","r":"'der skete i går' er en ledsætning, der står inde i sætningen. Kommaet skal stå, hvor den slutter."},
{"l":5800,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord i sætningen skal skrives med stort: 'Klassen gik fra banegården til tivoli og videre til rådhuset.'?","o":["banegården","tivoli","rådhuset","videre"],"a":"tivoli","r":"Tivoli er navnet på et bestemt sted og skrives med stort. Banegården og rådhuset er her almindelige fællesnavne."},
{"l":5815,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bakkeskolen har fået solceller på taget. Ifølge skoleinspektøren kan pengene, der spares på elregningen, bruges på nye bøger. Elevrådet håber dog, at en del går til bedre legepladser.' Hvad er skoleinspektøren og elevrådet ikke enige om?","o":["Om solcellerne faktisk sparer penge","Om taget kan bære solcellerne","Hvad de sparede penge skal bruges til","Hvem der har betalt for solcellerne"],"a":"Hvad de sparede penge skal bruges til","r":"Ordet 'dog' markerer forskellen: inspektøren nævner bøger, elevrådet legepladser. Begge regner med, at der bliver sparet penge."},
{"l":5837,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om Oscar og cyklen står i passiv?","o":["Oscar blev træt af cyklen.","Oscar har repareret cyklen.","Cyklen var blevet gammel.","Cyklen blev repareret af Oscar."],"a":"Cyklen blev repareret af Oscar.","r":"I passiv er det, der bliver gjort noget ved, grundled. 'Oscar blev træt af cyklen' har også 'blev' og 'af', men 'træt' er et tillægsord, så den sætning er ikke passiv."},
{"l":5858,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et brev begynder: 'Vedrørende din ansøgning'. Hvilket kort ord betyder her det samme som 'vedrørende'?","o":["om","mod","uden","før"],"a":"om","r":"'Vedrørende' fortæller, hvad brevet handler om. Det er et formelt ord, som næsten kun bruges på skrift."},
{"l":5876,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Det var ikke min ___ at gøre dig ked af det.'","o":["hensikt","hensigt","henssigt","hinsigt"],"a":"hensigt","r":"Ordet ender på -sigt ligesom 'udsigt' og skrives med g, selvom det lyder som k."},
{"l":5900,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvorfor står der ikke kolon efter 'råbte' i: 'Hun råbte, at det var nok.'?","o":["Fordi sætningen er for kort til kolon","Fordi 'råbte' ikke er et sige-ord","Fordi det er indirekte tale","Fordi replikken står i datid"],"a":"Fordi det er indirekte tale","r":"Kolon varsler personens egne ord. Her genfortæller sætningen med 'at', hvad hun råbte, og så skal der ikke kolon."},
{"l":5914,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Træneren siger, at holdet bliver hurtigere i nye, dyre støvler. Holdet fra Bakkegården vandt rækken i fjor. De spillede i støvler, de havde arvet fra de ældste årgange.' Hvad er skribentens indvending mod træneren?","o":["At nye støvler er for dyre til et lille hold","At brugte støvler holder længere end nye","At Bakkegården har et bedre hold end de selv","At man godt kan vinde uden nye støvler"],"a":"At man godt kan vinde uden nye støvler","r":"Bakkegården vandt rækken i gamle, arvede støvler. Det viser, at et hold ikke behøver nye støvler for at blive godt. Teksten nævner, at støvlerne er dyre, men det er ikke det, eksemplet handler om."},
{"l":5936,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning passer bedst i en mail til skolens leder?","o":["Jeg vil gerne høre, om vi må holde fest.","Jeg skal lige høre, om vi må holde fest.","Må vi ikke godt holde en fest, du?","Hej chef, vi vil gerne holde en fest."],"a":"Jeg vil gerne høre, om vi må holde fest.","r":"Til en leder skriver man høfligt og spørger pænt. 'Lige', 'du?' og 'chef' lyder som en snak mellem venner."},
{"l":5956,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er 'diskrimination'?","o":["at give alle mennesker nøjagtig den samme behandling","at behandle nogen dårligere på grund af, hvem de er","at undersøge, hvor mange der bor i et område","at flytte til et andet land for at finde arbejde"],"a":"at behandle nogen dårligere på grund af, hvem de er","r":"Diskrimination er forskelsbehandling, for eksempel på grund af køn, alder eller hudfarve. Det er ulovligt i mange sammenhænge."},
{"l":5978,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Der var en god atmosfære i klassen.' Hvad betyder 'atmosfære' i denne sætning?","o":["luftlag","undervisning","stemning","bygning"],"a":"stemning","r":"Atmosfære kan være luftlaget omkring Jorden, men om et rum eller en gruppe mennesker betyder ordet stemning."},
{"l":5993,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Problemet er ___, fordi ingen har læst vejledningen.'","o":["opståed","oppstået","opståt","opstået"],"a":"opstået","r":"Tillægsformen af 'opstå' ender på -et. Ordet har kun ét p."},
{"l":6005,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sætningsled er 'Bogen' i: 'Bogen gav jeg til Ida.'?","o":["genstandsled","grundled","udsagnsled","hensynsled"],"a":"genstandsled","r":"Spørg: Hvad gav jeg? Det gav jeg bogen, så den er genstandsled. Grundleddet er 'jeg', for det første led i sætningen er ikke altid grundled."},
{"l":6027,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket spørgsmål finder genstandsleddet i: 'Malthe købte en ny rygsæk i byen.'?","o":["Hvem købte en ny rygsæk?","Hvad købte Malthe?","Hvor købte Malthe rygsækken?","Hvordan var rygsækken?"],"a":"Hvad købte Malthe?","r":"Man finder genstandsleddet ved at spørge 'hvad/hvem' + verbum + grundled. 'Hvem købte …?' finder grundleddet."},
{"l":6046,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Annonce: Bliv klogere på sprog på 10 minutter om dagen! Tusindvis af glade brugere siger, at det virker. Prøv gratis i dag, inden tilbuddet udløber.' Hvad mangler i annoncen, hvis man vil vurdere påstanden?","o":["Oplysning om, hvor lang tid man skal bruge","En opfordring til at prøve det med det samme","Bevis for, at det faktisk virker","Et løfte om, at man bliver bedre til sprog"],"a":"Bevis for, at det faktisk virker","r":"Annoncen henviser kun til glade brugere, uden tal eller undersøgelser. De tre andre ting står i annoncen."},
{"l":6068,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mikkel siger til sin holdkammerat Asta: 'Jeg har en høne at plukke med dig.' Hvad mener han?","o":["at han vil takke hende for hjælp, hun har givet","at han vil invitere hende til at spise middag","at han vil låne noget af hende i weekenden","at han vil tale med hende om noget, han er sur over"],"a":"at han vil tale med hende om noget, han er sur over","r":"Talemåden betyder, at man har en uafklaret sag med nogen og vil have den talt igennem. Det har intet med madlavning at gøre."},
{"l":6090,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'På hylden i klubhuset står en pokal med teksten Nr. 2. Malte har stillet den, så teksten vender ind mod væggen. Træneren drejer den, hver gang han rydder op. Dagen efter vender den ind mod væggen igen.' Hvad viser det, at pokalen bliver ved med at blive drejet?","o":["De synes ikke det samme om den pokal","Træneren har ikke opdaget, at den er blevet flyttet","Malte vil gerne have, at alle ser teksten","Træneren er utilfreds med drengens indsats"],"a":"De synes ikke det samme om den pokal","r":"Malte gemmer teksten, fordi han kun blev nummer to. Træneren vender den tilbage igen og igen. Uden at sige noget viser de, at de ikke synes det samme om den."},
{"l":6101,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forsøg: To klasser fik samme test. Den ene sov otte timer før testen, den anden sov fem. Den første klasse scorede bedst. Forskerne skriver, at søvn kan have en betydning, men at klasserne også havde forskellige lærere.' Hvorfor er forskerne forsigtige?","o":["Testen var ens for de to klasser","Forskellen kan også skyldes lærerne","Otte timers søvn er for lidt til at måle","Klassernes elever fik samme karakterer"],"a":"Forskellen kan også skyldes lærerne","r":"Når to ting er forskellige mellem klasserne, kan man ikke vide, hvilken der gav forskellen. Derfor skriver forskerne 'kan have'."},
{"l":6123,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sofie stod med telefonen. 23 ulæste beskeder i klassens gruppe. Hun lagde den med skærmen nedad og gik hen for at vande en plante, der allerede var våd.' Hvad røber den sidste sætning om Sofie?","o":["At hun er meget optaget af havearbejde","At hun ikke har set, at planten er våd","At hun forsøger at undgå beskederne","At hun har glemt, hvor telefonen ligger"],"a":"At hun forsøger at undgå beskederne","r":"Planten er allerede våd, så den behøver ikke vand. Hun finder bare på noget at lave, så hun ikke skal læse beskederne."},
{"l":6141,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er den første fase i berettermodellen?","o":["klimaks","udtoning","konfliktoptrapning","anslag"],"a":"anslag","r":"Anslaget er åbningen, som skal fange publikum og sætte stemningen. Så følger præsentation, uddybning, optrapning, klimaks og udtoning."},
{"l":6160,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Freja siger noget, efter at hendes navn er nævnt. Hvilken sætning er rigtig?","o":["Freja spurgte: »Skal vi gå nu?«","Freja spurgte »: Skal vi gå nu?«","Freja spurgte, »Skal vi gå nu?«","»Freja spurgte: Skal vi gå nu?«"],"a":"Freja spurgte: »Skal vi gå nu?«","r":"Kolon står efter 'spurgte', og anførselstegnene omslutter kun replikken med dens spørgsmålstegn."},
{"l":6181,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor står 'ikke' efter verbet i 'Viktor spiser ikke fisk' og foran verbet i 'fordi Viktor ikke spiser fisk'?","o":["Den første er en ledsætning, den anden en hovedsætning.","Den første er en hovedsætning, den anden en ledsætning.","Den første er et udsagn, den anden et spørgsmål.","Den første er aktiv, den anden er passiv."],"a":"Den første er en hovedsætning, den anden en ledsætning.","r":"I en hovedsætning står 'ikke' efter verbet, og i en ledsætning står det foran verbet. 'Fordi' viser, at den anden er en ledsætning."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nye tilflyttere klager over lugten fra havnen. Jeg har boet her i 40 år, og det sjoveste, jeg har hørt, er folk, der flytter til en fiskerby og undrer sig over fisk.' Hvad mener skribenten?","o":["Havnen lugter værre nu, end den gjorde for 40 år siden","Byen burde lukke havnen for at gøre tilflytterne glade","Tilflytterne burde have vidst, hvad de flyttede til","Skribenten er lige så utilfreds som tilflytterne"],"a":"Tilflytterne burde have vidst, hvad de flyttede til","r":"Fisk hører til en fiskerby, og derfor er klagen i skribentens øjne komisk. Tonen er spottende, ikke medfølende."},
{"l":6214,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken del af 'skoletaske' afgør, at det hedder 'en skoletaske'?","o":["forleddet 'skole'","ordets første bogstav","ordets antal stavelser","efterleddet 'taske'"],"a":"efterleddet 'taske'","r":"I et sammensat ord er det efterleddet, der bestemmer ordets køn. Det hedder 'en taske', og derfor 'en skoletaske'."},
{"l":6236,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket udtryk er det rigtige i et formelt brev: '___ den nye cykelsti vil jeg gerne spørge om følgende.'?","o":["Med hensyn til","Med hensyn på","Med henblik til","I henhold om"],"a":"Med hensyn til","r":"Det faste udtryk hedder 'med hensyn til'. Forholdsordet hører med til udtrykket, og 'med henblik' skal have 'på' efter sig, ikke 'til'."},
{"l":6256,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'parlament'?","o":["et råd af dommere, der afgør store retssager","en forsamling af folkevalgte, der vedtager love","en gruppe ministre, der leder landet sammen","et kontor, der tæller stemmerne op"],"a":"en forsamling af folkevalgte, der vedtager love","r":"Det danske parlament er Folketinget. Ordet kommer af det franske 'parler', som betyder at tale."},
{"l":6279,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Søvn er helt ___, hvis kroppen skal have det godt.'","o":["nødvending","nødvenig","nødvendig","nødventig"],"a":"nødvendig","r":"Ordet kommer af tysk 'notwendig' og har to d'er. Det ender på -ig, ikke -ing."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da jeg var barn, troede jeg, at voksne vidste, hvad de lavede. Nu er jeg 15, og jeg har set dem samle et skab.' Hvad er pointen?","o":["Skribenten er blevet mere tilfreds med sine forældre","Skribenten vil gerne lære at samle møbler ordentligt","Skribenten mener, at skabe er for svære for børn","Skribenten har opdaget, at voksne også famler sig frem"],"a":"Skribenten har opdaget, at voksne også famler sig frem","r":"At samle et skab er svært, og skribenten har set de voksne bakse med det. Så er troen på, at voksne altid ved, hvad de laver, væk."},
{"l":6310,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Isbjørnens pels ser hvid ud, men hårene er gennemsigtige. Det hvide skær opstår, fordi lyset spredes i hårene. Under pelsen er huden sort.' Hvad kan man slutte ud fra teksten?","o":["En isbjørn uden pels ville se mørk ud","Isbjørnens hår er hvide helt igennem","Den sorte hud gør lyset i pelsen hvidt","Isbjørnen skifter farve efter årstiden"],"a":"En isbjørn uden pels ville se mørk ud","r":"Når huden under pelsen er sort, ville dyret se mørkt ud uden pels. Det hvide skyldes lyset i hårene, ikke huden."},
{"l":6331,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'I ___ af brand skal alle gå roligt ud ad nødudgangen.'","o":["tilfælle","tilfælde","tilfelde","tillfælde"],"a":"tilfælde","r":"Ordet indeholder 'fælde' med stumt d. Forstavelsen 'til-' skrives med ét l."},
{"l":6353,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'stereotyp'?","o":["et musikanlæg med to højttalere","en grundig undersøgelse af en gruppe mennesker","et forenklet billede af en gruppe mennesker","en beskrivelse af én bestemt persons liv"],"a":"et forenklet billede af en gruppe mennesker","r":"En stereotyp får alle i en gruppe til at se ens ud. Den overser, at mennesker er forskellige."},
{"l":6370,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Min onkel har startet en lille ___, der sælger cykler.'","o":["virkssomhed","virksomhet","virkesomhed","virksomhed"],"a":"virksomhed","r":"Ordet består af 'virksom' og '-hed'. Der er ét s og ét m, og endelsen skrives med d."},
{"l":6396,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes det element i en reklame, der først fanger øjet, f.eks. et stort billede?","o":["blikfang","målgruppe","afsender","hjemmel"],"a":"blikfang","r":"Blikfanget skal få os til at standse op og se på reklamen. Det kan være et billede, en farve eller en stor overskrift."},
{"l":6411,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken type ledsætning findes i: 'Jeg ved ikke, om Nadia kommer.'?","o":["relativsætning","spørgende ledsætning","at-sætning","adverbialsætning"],"a":"spørgende ledsætning","r":"Ledsætningen indeholder et spørgsmål, nemlig 'Kommer Nadia?'. Spørgende ledsætninger begynder ofte med 'om' eller et hv-ord."},
{"l":6431,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vores datter kan desværre ikke være med i skolens teater. Hun går allerede til violin, svømning, matematikhold og kinesisk. Hun elsker at have fart på, siger vi altid.' Hvad kan en opmærksom læser komme i tvivl om?","o":["Om datteren overhovedet har en violin","Om skolen faktisk har et teater for eleverne","Om det er datteren eller forældrene, der ønsker det","Om datteren er god til svømning og matematik"],"a":"Om det er datteren eller forældrene, der ønsker det","r":"Det er forældrene, der fortæller, og det er 'vi', der siger, hun elsker det. Datterens egen stemme hører man ikke."},
{"l":6451,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Læreren påpegede en fejl i opgaven.' Hvad gjorde læreren?","o":["lavede selv fejlen med vilje","undskyldte for fejlen","så bort fra fejlen","gjorde opmærksom på fejlen"],"a":"gjorde opmærksom på fejlen","r":"At påpege er at pege på noget med ord, så andre lægger mærke til det."},
{"l":6474,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Skolefesten er årets store ___.'","o":["begivenhed","begivendhed","begivenhet","bigivenhed"],"a":"begivenhed","r":"Ordet har ét g og ét n, og der er intet d foran -hed. Endelsen skrives med d til sidst."},
{"l":6497,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Nogle vil afskaffe pointene i skolens gymnastikkonkurrence. Men hvordan skal en gymnast vide, hvor hun står, uden et tal? Spørg bare en fodboldspiller, om han vil spille uden at tælle mål.' Hvilken antagelse bygger skribenten på?","o":["At fodboldspillere også får point for flotte mål","At man kun kan se, hvor man står, med et tal","At andre skoler heller ikke skal have point","At gymnaster er ligeglade med, hvordan det går dem"],"a":"At man kun kan se, hvor man står, med et tal","r":"Skribenten spørger 'hvordan … uden et tal?', som om der ikke er andre måder at vide det på. Men en træner kan jo også bare fortælle det."},
{"l":6503,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Nadia går med 'livrem og seler', når hun rejser. Hvad betyder det?","o":["hun klæder sig altid meget fint på","hun pakker altid alt for lidt med","hun sikrer sig dobbelt mod problemer","hun rejser helst uden nogen plan"],"a":"hun sikrer sig dobbelt mod problemer","r":"Både en livrem og et par seler holder bukserne oppe. Den, der bruger begge dele, tager ingen chancer."},
{"l":6526,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Vi skal læse første ___ i bogen til i morgen.'","o":["kapittel","kapitell","kabitel","kapitel"],"a":"kapitel","r":"Ordet har ét t i grundformen og slutter på -el med ét l."},
{"l":6543,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad hedder verbalformen 'Kør' på latin i: 'Kør forsigtigt på vejen.'?","o":["imperativ","infinitiv","præsens","præteritum"],"a":"imperativ","r":"'Kør' er en direkte opfordring, altså bydeform, og det hedder imperativ. Infinitiv er 'køre', præsens er 'kører', og præteritum er 'kørte'."},
{"l":6565,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Læger taler om 'diagnose' og 'fraktur'. Hvad kalder man den slags sprogbrug?","o":["dialekt","fagsprog","børnesprog","rigsdansk"],"a":"fagsprog","r":"Fagsprog er de særlige ord, som folk inden for et fag bruger for at være præcise."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
